# frozen_string_literal: true

require "json"

# The Rust secret-shape scan: every shape compiled once into a frozen set, and 1 crossing per text that
# returns every shape's matches in byte offsets. Agreement with Ruby is checked 2 ways, against the
# frozen corpus Ruby wrote and against the live Ruby regexes over generated bytes.
RSpec.describe Lain::Ext::Regions do
  let(:shapes) { Lain::Sensitivity::RustShapes }

  def corpus
    path = File.expand_path("../../../ext/lain/corpus/regions.ndjson", __dir__)
    File.foreach(path).map { JSON.parse(_1) }
  end

  def rust_ranges(scan, index, skip)
    scan.matches.select { _1[0] == index }.map do |_, start, finish, groups|
      named = groups.reject { |name, _| name.match?(/\A\d+\z/) }
      { "0" => [start + skip, finish + skip] }.merge(named.transform_values { |s, e| [s + skip, e + skip] })
    end
  end

  def ruby_ranges(regexp, bytes)
    names = regexp.names.uniq
    bytes.to_enum(:scan, regexp).map { Regexp.last_match }.map do |match|
      groups = names.empty? ? (1...match.size).to_a : names
      groups.each_with_object({ "0" => [match.begin(0), match.end(0)] }) do |group, out|
        out[group.to_s] = [match.begin(group), match.end(group)] if match.begin(group)
      end
    end
  end

  def rust_groups(scan, index)
    scan.matches.select { _1[0] == index }.map { |_, start, finish, groups| { "0" => [start, finish] }.merge(groups) }
  end

  describe "the frozen corpus" do
    it "reproduces every recorded range and named group, netrc's repeated value included" do
      disagreements = corpus.filter_map do |record|
        input, output = record.values_at("input", "output")
        bytes = [input.fetch("bytes")].pack("H*")
        skip = output.fetch("skip")
        got = rust_ranges(shapes.compiled.scan(bytes.byteslice(skip..)), shapes.names.index(input.fetch("shape")), skip)
        want = output.fetch("matches").map(&:compact)
        [input.values_at("shape", "label"), got, want] unless got == want
      end

      expect(disagreements).to be_empty
    end

    it "carries a netrc record whose password comes before its login" do
      record = corpus.find { _1.dig("input", "label") == "netrc password first" }

      expect(record.dig("output", "matches", 0, "value")).not_to be_nil
    end
  end

  describe "random bytes" do
    let(:seed) { Integer(ENV.fetch("LAIN_REGIONS_SEED", Random.new_seed.to_s)) % (2**32) }

    def fragments
      corpus.map { [_1.dig("input", "bytes")].pack("H*") } + ["\n", "\r\n", "\xff\xfe".b, "\x00", " ", "=", ":", "\t"]
    end

    def generated(rng, pieces)
      Array.new(1000) { Array.new(rng.rand(1..6)) { pieces[rng.rand(pieces.size)] }.join.b }
    end

    it "gives every match range Ruby gives over 1,000 generated byte strings" do
      rng = Random.new(seed)
      texts = generated(rng, fragments.map(&:b))
      regexps = shapes::SHAPES.values
      failures = texts.each_with_index.flat_map do |text, at|
        scan = shapes.compiled.scan(text)
        regexps.each_with_index.filter_map do |regexp, index|
          got = rust_groups(scan, index)
          want = ruby_ranges(regexp, text)
          [at, shapes.names[index], text, got, want] unless got == want
        end
      end

      expect(failures).to be_empty, "LAIN_REGIONS_SEED=#{seed} replays it: #{failures.first(3).inspect}"
    end
  end

  describe ".compile" do
    it "returns a frozen, Ractor-shareable set" do
      set = described_class.compile([%w[aws AKIA[0-9A-Z]{16}]])

      expect(set).to be_frozen
      expect(Ractor.shareable?(set)).to be(true)
    end

    it "raises BadShape, a Lain::Error, naming the shape that does not compile" do
      expect(described_class::BadShape.ancestors).to include(Lain::Error)
      expect { described_class.compile([%w[fine a], %w[broken (]]) }
        .to raise_error(described_class::BadShape, /"broken"/)
    end

    it "refuses a shape that is not a name and a source" do
      expect { described_class.compile([["only a name"]]) }.to raise_error(TypeError)
      expect { described_class.compile([["name", 1]]) }.to raise_error(TypeError)
    end
  end

  describe "Set#scan" do
    let(:set) { described_class.compile([%w[runaway ^(a|aa)+\1c], %w[aws AKIA[0-9A-Z]{16}]]) }

    it "reports a shape over its backtrack limit apart, while the others still match" do
      scan = set.scan("#{"a" * 60} AKIAABCDEFGHABCDEFGH")

      expect(scan.limited).to eq([0])
      expect(scan.matches).to eq([[1, 61, 81, {}]])
    end

    it "returns a deeply frozen, shareable scan" do
      scan = set.scan("AKIAABCDEFGHABCDEFGH")

      expect(scan.matches).to be_deeply_frozen
      expect(scan.limited).to be_deeply_frozen
      expect(Ractor.shareable?(scan)).to be(true)
    end

    it "scans the bytes of a String in any encoding, by byte offset" do
      text = "\xFF\xFE".b + "AKIAABCDEFGHABCDEFGH".encode(Encoding::UTF_16LE).b + "é AKIAABCDEFGHABCDEFGH".b

      expect(set.scan(text.force_encoding(Encoding::UTF_16LE)).matches).to eq([[1, 45, 65, {}]])
    end

    it "refuses a text that is not a String" do
      expect { set.scan(:symbol) }.to raise_error(TypeError, /String/)
    end
  end

  # 2 sets, because a stop request is read in 2 places: between matches, which only a shape that keeps
  # matching reaches, and between shapes, which only a set of shapes that never match depends on.
  describe "Set#scan with the lock released" do
    words = ("alpha beta gamma delta " * 100_000).freeze

    context "with 1 shape that matches all through a long text" do
      it_behaves_like "a GVL-releasing binding" do
        let(:matching) { described_class.compile([["word", '\w+(?=\s)']]) }
        let(:work) do
          compiled = matching
          -> { compiled.scan(words) }
        end
        let(:small_work) do
          compiled = matching
          small = words.byteslice(0, 4096)
          -> { compiled.scan(small) }
        end
        let(:complete) { ->(scan) { scan.matches.size == 400_000 } }
        let(:crowd_work) do
          compiled = matching
          crowd = "#{" " * (520 * 1024)}alpha beta "
          -> { compiled.scan(crowd).matches }
        end
        let(:crowd_complete) { ->(matches) { matches.map { _1[1] } == [520 * 1024, (520 * 1024) + 6] } }
      end
    end

    context "with many shapes that never match" do
      it_behaves_like "a GVL-releasing binding" do
        let(:never) { described_class.compile(Array.new(40) { |i| ["never #{i}", "[a-z]{#{6 + i},}"] }) }
        let(:work) do
          compiled = never
          -> { compiled.scan(words) }
        end
        let(:small_work) do
          compiled = never
          small = words.byteslice(0, 4096)
          -> { compiled.scan(small) }
        end
        let(:complete) { ->(scan) { scan.matches.empty? && scan.limited.empty? } }
        let(:crowd_work) do
          compiled = never
          crowd = words.byteslice(0, 520 * 1024)
          lambda do
            scan = compiled.scan(crowd)
            [scan.matches, scan.limited]
          end
        end
        let(:crowd_complete) { ->(answer) { answer == [[], []] } }
      end
    end
  end
end
